#define PAGE_SIZE_SHIFT 12
#define PTE_COUNT (1 << 10) // Total entries

typedef struct {
    unsigned long PFN : 20; // Physical Frame Number
    unsigned char V : 1;    // Valid bit
    unsigned char D : 1;    // Dirty bit
} PTE;

PTE PageTable[PTE_COUNT];
uintptr_t VA_OFFSET_MASK = (1UL << PAGE_SIZE_SHIFT) - 1;

uintptr_t translate_va(uintptr_t va) {
    uintptr_t vpn = va >> PAGE_SIZE_SHIFT;
    uintptr_t offset = va & VA_OFFSET_MASK;

    PTE entry = PageTable[vpn]; // Direct indexing

    if (!entry.V) return 0; // Page Fault (Indicate error/not mapped)

    return (entry.PFN << PAGE_SIZE_SHIFT) | offset;
}
